import { notices, grayscale } from './colors';
import { base } from './base';

const colors = {
  green: '#22b24e',
  orange: '#5292c6',
  orangeAccent: '#e56209',
  navy: '#5292c6',
  blue: '#2d9dd6',
  blueAccent: '#82c1e0',
  yellow: '#ffed00',
  footerDark: '#0B4892',
  lightBlue: '#95b3de',
  darkBlue: '#1b1d39',
  ...grayscale,
  ...notices,
};

const baseVariants = {
  a: {
    primary: colors.navy,
    secondary: colors.blue,
    tertiary: colors.lightBlue,
    accent: colors.lightBlue,
    accentAccent: colors.lightBlue,
    background: colors.white,
    text: colors.dark,
    link: colors.navy,
    inverseText: colors.white,
    linkHover: colors.lightBlue,
    shape: colors.lightBlue,
    ...grayscale,
    ...notices,
  },
  b: {
    primary: colors.white,
    secondary: colors.white,
    tertiary: colors.white,
    accent: colors.blue,
    accentAccent: colors.blueAccent,
    background: colors.navy,
    text: colors.white,
    link: colors.lightest,
    inverseText: colors.white,
    linkHover: colors.orange,
    shape: colors.lightBlue,
    ...grayscale,
    ...notices,
  },
  c: {
    primary: colors.yellow,
    secondary: colors.white,
    tertiary: colors.white,
    accent: colors.orange,
    accentAccent: colors.orangeAccent,
    background: colors.blue,
    text: colors.white,
    link: colors.lightest,
    inverseText: colors.white,
    linkHover: colors.orangeAccent,
    shape: colors.lightBlue,
    ...grayscale,
    ...notices,
  },
  d: {
    primary: colors.navy,
    secondary: colors.blue,
    tertiary: colors.green,
    accent: colors.orange,
    accentAccent: colors.orangeAccent,
    background: colors.footerDark,
    text: colors.white,
    link: colors.lightest,
    inverseText: colors.white,
    linkHover: colors.orange,
    shape: colors.lightBlue,
    ...grayscale,
    ...notices,
  },
};

const variants = Object.assign(baseVariants, {
  e: {
    ...baseVariants.a,
    text: colors.orange,
    secondary: colors.orangeAccent,
  },
  f: {
    ...baseVariants.a,
    secondary: colors.orange,
  },
  g: {
    ...baseVariants.a,
    accent: '#1566ad',
    link: '#1566ad',
    linkHover: '#ef8612',
  },
  h: {
    ...baseVariants.a,
    background: colors.orange,
    text: colors.white,
    primary: colors.white,
  },
  i: {
    ...baseVariants.a,
    background: colors.navy,
    primary: colors.orange,
    text: colors.white,
  },
  j: {
    ...baseVariants.a,
    background: '#f7a91c',
    primary: colors.white,
    text: '#0b4892',
  },
  regular: {
    ...baseVariants.a,
    text: '#1566ad',
    tertiary: '#565656',
  },
});

export default {
  logoGlyph: 'obs',
  ...base,
  colors: {
    ...base.colors,
    variants,
  },
  button: {
    borderRadius: '3px',
  },
};
